import json, pathlib, re, statistics, collections
for step in [0,50,100]:
 p=pathlib.Path(f'results/run100/val_generations/{step}.jsonl')
 rows=[json.loads(x) for x in p.read_text().splitlines()]
 stats=collections.Counter(); lens=[]; pos=[]; examples=[]
 for r in rows:
  out=r['output']; gold=str(r['gts']).replace(',','').strip()
  lens.append(len(out)); trunc=len(out)>=0 # token len unavailable
  nums=re.findall(r'-?\d[\d,]*(?:\.\d+)?',out)
  norm=lambda x: x.replace(',','').rstrip('.').lstrip('0') or '0'
  ng=norm(gold)
  anyg=ng in {norm(n) for n in nums}
  marker=re.findall(r'####\s*(-?\d[\d,]*(?:\.\d+)?)',out)
  marker_norm=norm(marker[-1]) if marker else None
  # final numeric token
  last=norm(nums[-1]) if nums else None
  stats['rows']+=1; stats['any_gold']+=anyg; stats['has_marker']+=bool(marker); stats['marker_correct']+=(marker_norm==ng); stats['last_correct']+=(last==ng); stats['logged_score']+=float(r.get('score',0)); stats['len>=?']+=len(out)>=3000
  if anyg and not marker: stats['any_no_marker']+=1
  if marker and marker_norm==ng: pos.append(out.find('####'))
  if len(out)>3000: stats['long']+=1
  if marker: stats['marker_count']+=len(marker)
  if anyg and not (marker_norm==ng):
   if len(examples)<3: examples.append((gold,out[-500:]))
 print('\nstep',step, stats, 'mean chars',statistics.mean(lens),'median',statistics.median(lens),'marker_pos mean',statistics.mean(pos) if pos else None)
 print('examples any gold but marker wrong/no:',examples)
PY",workdir:"/workspace",yield_time_ms:10000,max_output_tokens:20000});
text(r.output);

