const r = await tools.exec_command({cmd:"python3 - <<'PY'
import json,re,pathlib,collections,statistics
for step in [0,50,100]:
 rows=[json.loads(x) for x in pathlib.Path(f'results/run100/val_generations/{step}.jsonl').read_text().splitlines()]
 C=collections.Counter()
 for r in rows:
  out=r['output']; gold=str(r['gts'])
  norm=lambda x: x.replace(',','').replace('$','').strip().rstrip('.').lstrip('0') or '0'
  g=norm(gold)
  # common parser candidates
  patterns={
   'boxed':re.findall(r'\\boxed\s*\{\s*(-?\d[\d,]*(?:\.\d+)?)\s*\}',out),
   'last_boxed_any':re.findall(r'\\boxed\s*\{([^{}]*)\}',out),
   'final_answer':re.findall(r'(?:final answer|answer is|answer:)\s*[^\n]*?(-?\d[\d,]*(?:\.\d+)?)',out,re.I),
   'last_num':re.findall(r'-?\d[\d,]*(?:\.\d+)?',out),
   'dollar':re.findall(r'\$\s*(-?\d[\d,]*(?:\.\d+)?)',out),
  }
  for k,vals in patterns.items():
   if vals:
    v=vals[-1]
    # last_boxed_any may not numeric
    m=re.search(r'-?\d[\d,]*(?:\.\d+)?',v)
    if m:v=m.group(0)
    C[k]+=norm(v)==g
  C['any_num']+=g in {norm(v) for v in patterns['last_num']}
 print(step, {k:(v,len(rows),v/len(rows)) for k,v in C.items()})
PY",workdir:"/workspace",yield_time_ms:10000,max_output_tokens:10000});
text(r.output);

