const r = await tools.exec_command({cmd:"python3 - <<'PY'
import json,re,pathlib,collections,statistics
# built-in strict: clips last 300 chars then finds #### number, compares exact ground_truth (already commas removed)
def strict(out,g):
 out=out[-300:] if len(out)>300 else out
 a=re.findall(r'#### (-?[0-9.,]+)',out)
 return bool(a) and a[-1].replace(',','').replace('$','')==str(g)
def flex(out,g):
 a=re.findall(r'(-?[0-9.,]+)',out); return bool(a) and a[-1].replace(',','')==str(g)
for typ in ['val_generations','rollouts']:
 for step in [0,1,50,100]:
  p=pathlib.Path(f'results/run100/{typ}/{step}.jsonl')
  if not p.exists():continue
  rows=[json.loads(x) for x in p.read_text().splitlines()]
  vals=[strict(r['output'],r['gts']) for r in rows]
  vals2=[flex(r['output'],r['gts']) for r in rows]
  print(typ,step,'strict',sum(vals),len(vals),sum(vals)/len(vals),'flex-last',sum(vals2)/len(vals2),'logged',sum(float(r.get('score',0)) for r in rows)/len(rows))
PY",workdir:"/workspace",yield_time_ms:10000,max_output_tokens:10000});
text(r.output);

